    // base variants, and Header/ListMenu are partial overrides of components whose other
    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];

    const unexpected = Object.keys(components)
      .filter((name) => !INTENTIONAL_MERGES.includes(name))
      .filter((name) => {
        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
        const ourKeys = new Set(Object.keys(ours as object));
        // A key present after composition that we never declared came from the base theme.
        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
      });

    expect(unexpected).toEqual([]);
  });
});

