// Prototype button dimensions. The Handover's action tokens specify 52px (lg) / 40px
// (md) — see actionSizes in foundation/sizes.ts. Reconciling prototype ↔ Handover is a
// UI-designer decision (Hard Rule #3), so the prototype values are named here to make
// the temporary exception explicit rather than switched silently. The 5px vertical
// padding has no token counterpart.
const BTN_HEIGHT_LG = '50px';
const BTN_HEIGHT_SM = '41px';
const BTN_PADDING_Y = '5px';

// `textStyle` is a special key Chakra's style engine expands wherever it appears (see
// link.ts) — resolves against the full registered textStyles.button/buttonSm
// (foundation/typography.ts), the single source for fontFamily/fontSize/fontWeight/
// lineHeight/letterSpacing/textTransform.
const sizes = {
  lg: {
    h: BTN_HEIGHT_LG,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'button',
  },
  sm: {
    h: BTN_HEIGHT_SM,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'buttonSm',
  },
  // Auto-height for icon-only buttons; p resolves via Chakra's space scale (spacing.xs = 0.5rem).
  icon: {
    h: 'auto',
    minW: 'auto',
    p: 'xs',
  },
};

export const Button = defineStyleConfig({
  baseStyle,
  variants,
  sizes,
  defaultProps: {
    variant: 'primary',
    size: 'lg',
  },
});

