cd /tmp && cat > fm.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
for (const w of [320,360,375,384,390,414,480,600,767,768,1024]) {
  const p = await b.newPage({ viewport:{width:w,height:900} });
  try {
    await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded', timeout:45000 });
    await p.waitForTimeout(1200);
    const r = await p.evaluate(() => {
      const f = document.querySelector('footer[role="contentinfo"]');
      if (!f) return {err:'no footer'};
      // nav columns = children of the links inner flex container
      const heads = [...f.querySelectorAll('p')].filter(e=>/^(ABOUT|CONTACT|HELP)$/i.test(e.textContent.trim()));
      const cols = heads.map(h=>{const r=h.getBoundingClientRect();return {t:Math.round(r.top),l:Math.round(r.left),txt:h.textContent.trim()};});
      const rows = [...new Set(cols.map(c=>c.t))].length;
      return {cols, rowsOfHeadings: rows};
    });
    console.log(`w=${String(w).padEnd(5)} rows=${r.rowsOfHeadings ?? '-'} ${JSON.stringify(r.cols ?? r.err)}`);
  } catch(e){ console.log(`w=${w} ERR ${e.message.split('\n')[0]}`); }
  await p.close();
}
await b.close();
EOF
